files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --input-bg: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  color: var(--muted);
  margin-bottom: 24px;
  font-size: 1rem;
}

.guess-area {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  align-items: center;
  margin-bottom: 16px;
}

label {
  font-size: 1rem;
  color: var(--muted);
}

input[type="number"] {
  width: 100px;
  padding: 10px;
  font-size: 1rem;
  border: 2px solid var(--accent);
  border-radius: 4px;
  background: var(--input-bg);
  color: var(--text);
  text-align: center;
  font-family: inherit;
}

input[type="number"]:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button {
  padding: 10px 20px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--bg);
  background: var(--accent);
  border: 2px solid var(--accent);
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

button:hover {
  background: #ff6b81;
  border-color: #ff6b81;
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

.feedback {
  min-height: 1.5em;
  font-size: 1.25rem;
  font-weight: bold;
  margin: 16px 0;
  color: var(--accent);
}

.guess-count {
  margin-bottom: 20px;
  color: var(--muted);
  font-size: 1rem;
}

#newGameBtn {
  background: transparent;
  color: var(--accent);
  border-color: var(--accent);
}

#newGameBtn:hover {
  background: var(--accent);
  color: var(--bg);
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .guess-area {
    flex-direction: column;
  }
  input[type="number"] {
    width: 100%;
  }
  button {
    width: 100%;
  }
}

let secretNumber;
let guessCount;

const guessInput = document.getElementById('guessInput');
const guessBtn = document.getElementById('guessBtn');
const newGameBtn = document.getElementById('newGameBtn');
const feedback = document.getElementById('feedback');
const guessCountEl = document.getElementById('guessCount');

function startGame() {
  secretNumber = Math.floor(Math.random() * 100) + 1;
  guessCount = 0;
  guessCountEl.textContent = '0';
  feedback.textContent = '';
  guessInput.value = '';
  guessInput.disabled = false;
  guessBtn.disabled = false;
  guessInput.focus();
}

function handleGuess() {
  const raw = guessInput.value.trim();
  if (raw === '') {
    feedback.textContent = 'Please enter a number.';
    return;
  }
  const guess = Number(raw);
  if (!Number.isInteger(guess) || guess < 1 || guess > 100) {
    feedback.textContent = 'Enter a whole number between 1 and 100.';
    return;
  }
  guessCount++;
  guessCountEl.textContent = guessCount;

  if (guess === secretNumber) {
    feedback.textContent = 'Correct! You got it in ' + guessCount + ' guess' + (guessCount === 1 ? '' : 'es') + '.';
    guessInput.disabled = true;
    guessBtn.disabled = true;
  } else if (guess > secretNumber) {
    feedback.textContent = 'Too high!';
  } else {
    feedback.textContent = 'Too low!';
  }
  guessInput.select();
}

guessBtn.addEventListener('click', handleGuess);
guessInput.addEventListener('keydown', function (e) {
  if (e.key === 'Enter') {
    handleGuess();
  }
});
newGameBtn.addEventListener('click', startGame);

startGame();
